#include <errno.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#include "base64.h"
#include "lwan-cache.h"
#include "lwan-config.h"
#include "lwan-http-authorize.h"

struct realm_password_file_t {
    struct cache_entry base;
    struct hash *entries;
};

static struct cache *realm_password_cache = NULL;

static void fourty_two_and_free(void *str)
{
    if (LIKELY(str)) {
        char *s = str;
        while (*s)
            *s++ = 42;
        free(str);
    }
}

static struct cache_entry *create_realm_file(
          const char *key,
          void *context __attribute__((unused)))
{
    struct realm_password_file_t *rpf = malloc(sizeof(*rpf));
    struct config *f;
    struct config_line l;

    if (UNLIKELY(!rpf))
        return NULL;

    rpf->entries = hash_str_new(fourty_two_and_free, fourty_two_and_free);
    if (UNLIKELY(!rpf->entries))
        goto error_no_close;

    f = config_open(key);
    if (!f)
        goto error_no_close;

    while (config_read_line(f, &l)) {
        /* FIXME: Storing plain-text passwords in memory isn't a good idea. */
        switch (l.type) {
        case CONFIG_LINE_TYPE_LINE: {
            char *username = strdup(l.key);
            if (!username)
                goto error;

            char *password = strdup(l.value);
            if (!password) {
                free(username);
                goto error;
            }

            int err = hash_add_unique(rpf->entries, username, password);
            if (LIKELY(!err))
                continue;

            free(username);
            free(password);

            if (err == -EEXIST) {
                lwan_status_warning(
                    "Username entry already exists, ignoring: \"%s\"",
                    l.key);
                continue;
            }

            goto error;
        }
        default:
            config_error(f, "Expected username = password");
            break;
        }
    }

    if (config_last_error(f)) {
        lwan_status_error("Error on password file \"%s\", line %d: %s",
